"""Sharded (tensor-parallel) PCC test for sparse_moe_block — auto-generated by tt_hw_planner.

Runs the SAME component against the SAME captured golden as test_sparse_moe_block.py, but on a TP mesh
(MeshShape(1, TP) via the mesh_device fixture). The stub shards its OWN weights (ShardTensorToMesh) and
does its collective internally; this harness replicates the input, runs on the mesh, gathers the
output, and PCC-compares. It imports the single-device test's helpers by path so the reference and
build path are byte-identical — only the device is a mesh. TT_HW_PLANNER_SHARD_TP sets the TP degree.
"""
from __future__ import annotations

import importlib.util
import os
from pathlib import Path

import pytest
import torch

import ttnn
from models.common.utility_functions import comp_pcc

_SIBLING = Path(__file__).resolve().parent / "test_sparse_moe_block.py"
_spec = importlib.util.spec_from_file_location("_sd_sparse_moe_block", _SIBLING)
_sd = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_sd)

_TP = int(os.environ.get("TT_HW_PLANNER_SHARD_TP", "2"))
_DP = int(os.environ.get("TT_HW_PLANNER_SHARD_DP", "1"))


def _system_mesh_shape():
    """The machine's full SystemMesh shape as a (rows, cols) tuple, or None if unavailable."""
    try:
        shape = ttnn._ttnn.multi_device.SystemMeshDescriptor().shape()
        dims = [int(d) for d in shape]
    except Exception:
        return None
    return tuple(dims) if len(dims) == 2 else None


# WHICH MESH THE FIXTURE OPENS is not the same question as WHICH MESH THE COMPONENT RUNS ON.
#
# What is under test is the TENSOR-PARALLEL scheme: gathered output == single-device golden. Data
# parallelism is pure replication of the same weights over disjoint batches, so it cannot change
# numerics and contributes nothing here -- the component runs on a (1, TP) mesh, not (DP, TP).
# Requesting (DP, TP) directly fails twice over on this machine: the manifest asks for DP=16/TP=2
# while the SystemMesh is MeshShape([8, 4]), which the runtime rejects as "too big and not
# rotatable"; and a bare MeshShape(1, 2) open dies in fabric bring-up with "Fabric Router Sync:
# Timeout ... Ethernet handshake likely failed" -- on a Galaxy the routers on a partial mesh try to
# handshake over links whose remote partner is outside the mesh and has no router kernel running.
#
# So: open the FULL SystemMesh (fabric initializes cleanly, every link has its partner) and carve a
# (1, TP) submesh out of it for the component. Verified on this box: all_reduce, all_gather and a
# row-parallel matmul + all_reduce on that submesh all match their torch references.
_SYS_MESH = _system_mesh_shape()
_MESH = _SYS_MESH if (_SYS_MESH and _SYS_MESH[0] * _SYS_MESH[1] > _TP) else _TP


@pytest.mark.parametrize(
    "device_params",
    [{"l1_small_size": 24576, "fabric_config": ttnn.FabricConfig.FABRIC_1D}],
    indirect=True,
)
@pytest.mark.parametrize("mesh_device", [_MESH], indirect=True)
def test_sparse_moe_block_sharded(mesh_device):
    torch.manual_seed(int(os.environ.get("TT_PLANNER_TEST_SEED", "0") or "0"))

    # Carve the TP group out of the full mesh; the `mesh_device` fixture closes submeshes on teardown.
    if mesh_device.get_num_devices() > _TP:
        tp_mesh = mesh_device.create_submesh(ttnn.MeshShape(1, _TP))
    else:
        tp_mesh = mesh_device
    assert tp_mesh.get_num_devices() == _TP, (
        f"TP group has {tp_mesh.get_num_devices()} devices, expected TP={_TP}"
    )

    torch_module, sample_kwargs, primary = _sd._build_torch_reference()
    try:
        torch_module = torch_module.float()
    except Exception:
        pass
    for _k in list(sample_kwargs.keys()):
        _v = sample_kwargs[_k]
        if isinstance(_v, torch.Tensor) and _v.is_floating_point():
            sample_kwargs[_k] = _v.to(torch.float32)
    _pn, _pt = primary
    if isinstance(_pt, torch.Tensor) and _pt.is_floating_point():
        primary = (_pn, _pt.to(torch.float32))

    with torch.no_grad():
        try:
            torch_out = torch_module(**sample_kwargs)
        except Exception as exc:
            pytest.skip(f"HF reference forward raised {type(exc).__name__}: {exc}")
    torch_out = _sd._normalize_out(torch_out)

    ttnn_module = _sd._build_ttnn_port(tp_mesh, torch_module)
    primary_name, primary_tensor = primary
    ttnn_input = _sd._ttnn_from_torch_mesh_safe(primary_tensor, tp_mesh)
    extra = {k: v for k, v in sample_kwargs.items() if k != primary_name}
    ttnn_out = ttnn_module(ttnn_input, **extra)
    if isinstance(ttnn_out, tuple) and ttnn_out:
        ttnn_out = ttnn_out[0]
    ttnn_out_torch = _sd._ttnn_to_torch_mesh_safe(ttnn_out, tp_mesh).to(torch.float32)

    if isinstance(torch_out, torch.Tensor):
        torch_out = torch_out.to(torch.float32)

    ok, pcc = comp_pcc(torch_out, ttnn_out_torch, _sd.PCC_TARGET)
    print(
        f"[bringup] SHARDED PCC={pcc} target={_sd.PCC_TARGET} tp={_TP} "
        f"component={_sd.COMPONENT_NAME}",
        flush=True,
    )
    assert ok, f"sharded PCC {pcc} below target {_sd.PCC_TARGET} for {_sd.COMPONENT_NAME} at TP={_TP}"


if __name__ == "__main__":
    import sys

    sys.exit(pytest.main([__file__, "-svv"]))
